from fractions import Fraction
import math

def floor_log2_fraction(p, q):
    # p,q positive integers; return floor(log2(p/q))
    # initial estimate
    L = p.bit_length() - q.bit_length()
    # adjust: need 2^L <= p/q < 2^(L+1)
    while True:
        if L >= 0:
            # p/q >= 2^L iff p >= q << L
            if p < (q << L):
                L -= 1
                continue
            # p/q < 2^(L+1) iff p < q << (L+1)
            if p >= (q << (L+1)):
                L += 1
                continue
        else:
            # p/q >= 2^L iff p << (-L) >= q
            if (p << (-L)) < q:
                L -= 1
                continue
            if (p << (-L-1)) >= q:
                L += 1
                continue
        return L

def round_fraction_to_int(t, mode, sign_negative):
    # t positive Fraction, round to integer
    num = t.numerator
    den = t.denominator
    floor = num // den
    rem = num - floor * den
    if rem == 0:
        return floor
    if mode == 'RTZ':
        return floor
    if mode == 'RNE':
        twice = rem * 2
        if twice > den:
            return floor + 1
        if twice == den:
            return floor + (floor & 1)
        return floor
    if mode == 'RNA':
        return floor + 1 if rem * 2 >= den else floor
    if mode == 'RUP':
        return floor if sign_negative else floor + 1
    if mode == 'RDN':
        return floor + 1 if sign_negative else floor
    raise ValueError

def decode(v, ebits, fbits, bias, Eall, F):
    sign = (v >> (ebits+fbits)) & 1
    e = (v >> fbits) & Eall
    f = v & (F-1)
    if e == Eall:
        if f == 0:
            return ('inf', sign)
        return ('nan', (f & (1 << (fbits-1))) == 0)
    if e == 0:
        if f == 0:
            return ('zero', sign)
        return ('finite', sign, Fraction(f) * Fraction(2)**(1-bias-fbits))
    return ('finite', sign, Fraction(F+f) * Fraction(2)**(e-bias-fbits))

def encode_value(sign, actual, ebits, fbits, bias, Eall, F):
    # actual positive Fraction
    if actual == 0:
        return sign << (ebits+fbits)
    emin = 1-bias
    if actual < Fraction(2)**emin:
        n = actual / (Fraction(2)**(emin-fbits))
        assert n.denominator == 1 and n < F, (actual, n)
        return (sign << (ebits+fbits)) | int(n)
    # normal
    L = floor_log2_fraction(actual.numerator, actual.denominator)
    e = L + bias
    sig = actual / (Fraction(2)**(e-bias-fbits))
    assert sig.denominator == 1 and F <= sig < 2*F, (actual, sig)
    return (sign << (ebits+fbits)) | (e << fbits) | (int(sig)-F)

def solve_ref(request):
    ebits=request['ebits']; fbits=request['fbits']; mode=request['mode']; pairs=request['pairs']
    width=1+ebits+fbits; F=1<<fbits; bias=(1<<(ebits-1))-1; Eall=(1<<ebits)-1
    emin=1-bias; emax=Eall-1-bias
    canonical_nan=(Eall<<fbits)|(1<<(fbits-1))
    dec=[]
    any_nan=False; any_snan=False
    for a,b in pairs:
        da=decode(int(a,16),ebits,fbits,bias,Eall,F)
        db=decode(int(b,16),ebits,fbits,bias,Eall,F)
        dec.append((da,db))
        for d in (da,db):
            if d[0]=='nan':
                any_nan=True
                if d[1]: any_snan=True
    invalid=any_snan
    inf_signs=set()
    prods=[]  # Fractions
    prod_signs=[]  # for zero products
    total=len(dec)
    for da,db in dec:
        if da[0]=='nan' or db[0]=='nan':
            continue
        if da[0]=='inf' or db[0]=='inf':
            if da[0]=='zero' or db[0]=='zero':
                invalid=True
            else:
                inf_signs.add(da[1]^db[1])
            continue
        s=da[1]^db[1]
        if da[0]=='zero' or db[0]=='zero':
            prod_signs.append(s)
        else:
            val=da[2]*db[2]
            if s: val=-val
            prods.append(val)
    if len(inf_signs)>1: invalid=True
    if invalid:
        return {'bits':format(canonical_nan,'x'),'flags':['invalid']}
    if any_nan:
        return {'bits':format(canonical_nan,'x'),'flags':[]}
    if inf_signs:
        sign=next(iter(inf_signs))
        return {'bits':format((sign<<(ebits+fbits))|(Eall<<fbits),'x'),'flags':[]}
    # finite
    if prods:
        total_val=sum(prods, Fraction(0))
        if total_val==0:
            sign=1 if mode=='RDN' else 0
            return {'bits':format(sign<<(width-1),'x'),'flags':[]}
        sign_neg = total_val<0
        x=abs(total_val)
    else:
        all_neg_zero = total>0 and len(prod_signs)==total and all(s==1 for s in prod_signs)
        if mode=='RDN' or all_neg_zero:
            sign=1
        else:
            sign=0
        return {'bits':format(sign<<(width-1),'x'),'flags':[]}
    L=floor_log2_fraction(x.numerator, x.denominator)
    q_exp=max(emin-fbits, L-fbits)
    quantum=Fraction(2)**q_exp
    t=x/quantum
    n=round_fraction_to_int(t,mode,sign_neg)
    actual=Fraction(n)*quantum
    flags=[]
    if actual!=x: flags.append('inexact')
    if actual >= Fraction(2)**(emax+1):
        flags=['overflow','inexact']
        to_inf=(mode in ('RNE','RNA')) or (mode=='RUP' and not sign_neg) or (mode=='RDN' and sign_neg)
        if to_inf:
            bits=(1 if sign_neg else 0)<<(ebits+fbits) | (Eall<<fbits)
        else:
            bits=(1 if sign_neg else 0)<<(ebits+fbits) | ((Eall-1)<<fbits) | (F-1)
        return {'bits':format(bits,'x'),'flags':flags}
    if actual!=x and actual < Fraction(2)**emin:
        flags.append('underflow')
    bits=encode_value(1 if sign_neg else 0, actual, ebits, fbits, bias, Eall, F)
    return {'bits':format(bits,'x'),'flags':flags}
