import json
import sys


def decode_operand(v, ebits, fbits, bias, Eall, F):
    """Return a tuple describing the operand.

    ('zero', sign)          finite zero
    ('finite', sign, sig, exp)
    ('inf', sign)
    ('nan', signaling)
    """
    width = 1 + ebits + fbits
    sign = (v >> (ebits + fbits)) & 1
    e = (v >> fbits) & Eall
    f = v & (F - 1)
    if e == Eall:
        if f == 0:
            return ('inf', sign)
        signaling = (f & (1 << (fbits - 1))) == 0
        return ('nan', signaling)
    if e == 0:
        if f == 0:
            return ('zero', sign)
        return ('finite', sign, f, 1 - bias - fbits)
    return ('finite', sign, F + f, e - bias - fbits)


def round_magnitude(N, D, mode, sign_negative):
    """Round the positive rational N/D to an integer.

    sign_negative is the sign of the exact value, used by directed modes.
    Returns (n, rem) where rem is the non-zero remainder of N/D, or 0 if exact.
    """
    floor = N // D
    rem = N - floor * D
    if rem == 0:
        return floor, 0
    if mode == 'RTZ':
        n = floor
    elif mode == 'RNE':
        twice = rem * 2
        if twice > D:
            n = floor + 1
        elif twice == D:
            n = floor + (floor & 1)
        else:
            n = floor
    elif mode == 'RNA':
        if rem * 2 >= D:
            n = floor + 1
        else:
            n = floor
    elif mode == 'RUP':
        # toward +infinity
        if sign_negative:
            n = floor
        else:
            n = floor + 1
    elif mode == 'RDN':
        # toward -infinity
        if sign_negative:
            n = floor + 1
        else:
            n = floor
    else:
        raise ValueError('bad rounding mode')
    return n, rem


def encode_inf(sign, ebits, fbits, Eall):
    return (sign << (ebits + fbits)) | (Eall << fbits)


def encode_max_finite(sign, ebits, fbits, Eall, F):
    return (sign << (ebits + fbits)) | ((Eall - 1) << fbits) | (F - 1)


def solve(request):
    ebits = int(request['ebits'])
    fbits = int(request['fbits'])
    mode = str(request['mode']).upper()
    pairs = request.get('pairs', [])
    width = 1 + ebits + fbits
    F = 1 << fbits
    bias = (1 << (ebits - 1)) - 1
    Eall = (1 << ebits) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    canonical_nan = (Eall << fbits) | (1 << (fbits - 1))

    # Decode all operands first: every operand must be inspected.
    decoded = []
    any_nan = False
    any_signaling_nan = False
    for pair in pairs:
        a = decode_operand(int(pair[0], 16), ebits, fbits, bias, Eall, F)
        b = decode_operand(int(pair[1], 16), ebits, fbits, bias, Eall, F)
        decoded.append((a, b))
        if a[0] == 'nan':
            any_nan = True
            if a[1]:
                any_signaling_nan = True
        if b[0] == 'nan':
            any_nan = True
            if b[1]:
                any_signaling_nan = True

    invalid = any_signaling_nan
    inf_signs = set()
    finite_products = []   # (sign, sig, exp) for non-zero finite products
    zero_product_signs = []  # signs of products that are exactly zero
    total_products = len(decoded)

    for a, b in decoded:
        a_kind = a[0]
        b_kind = b[0]
        # NaN pairs contribute nothing at all.
        if a_kind == 'nan' or b_kind == 'nan':
            continue
        a_sign = a[1]
        b_sign = b[1]
        if a_kind == 'inf' or b_kind == 'inf':
            if a_kind == 'zero' or b_kind == 'zero':
                invalid = True
            else:
                # one or both are infinite; the other is a non-zero finite
                inf_signs.add(a_sign ^ b_sign)
            continue
        # both operands are finite
        prod_sign = a_sign ^ b_sign
        if a_kind == 'zero' or b_kind == 'zero':
            zero_product_signs.append(prod_sign)
        else:
            finite_products.append((prod_sign, a[2] * b[2], a[3] + b[3]))

    if len(inf_signs) > 1:
        # Both signs of infinite products were present.
        invalid = True

    if invalid:
        return {'bits': format(canonical_nan, 'x'), 'flags': ['invalid']}
    if any_nan:
        return {'bits': format(canonical_nan, 'x'), 'flags': []}

    if inf_signs:
        sign = next(iter(inf_signs))
        return {'bits': format(encode_inf(sign, ebits, fbits, Eall), 'x'), 'flags': []}

    # All products are finite.  Compute the exact sum.
    if finite_products:
        min_exp = min(exp for _, _, exp in finite_products)
        total = 0
        for sign, sig, exp in finite_products:
            term = sig << (exp - min_exp)
            if sign:
                total -= term
            else:
                total += term
        if total == 0:
            # Exact cancellation involving non-zero products.
            sign = 1 if mode == 'RDN' else 0
            return {'bits': format(sign << (width - 1), 'x'), 'flags': []}
        sign_negative = total < 0
        M = abs(total)
        E = min_exp
    else:
        # No non-zero products: the exact sum is zero.
        all_negative_zero_products = (
            total_products > 0 and len(zero_product_signs) == total_products
            and all(s == 1 for s in zero_product_signs)
        )
        if mode == 'RDN' or all_negative_zero_products:
            sign = 1
        else:
            sign = 0
        return {'bits': format(sign << (width - 1), 'x'), 'flags': []}

    # Round the exact non-zero magnitude M * 2**E.
    L = M.bit_length() - 1 + E
    q_exp = max(emin - fbits, L - fbits)
    shift = E - q_exp
    if shift >= 0:
        N = M << shift
        D = 1
    else:
        N = M
        D = 1 << (-shift)

    n, rem = round_magnitude(N, D, mode, sign_negative)
    actual_exp = q_exp
    # actual = n * 2**q_exp
    if n == 0:
        # Non-zero exact value rounded to zero.
        flags = ['inexact', 'underflow']
        return {'bits': format((1 if sign_negative else 0) << (width - 1), 'x'), 'flags': flags}

    k = actual_exp + n.bit_length() - 1  # floor(log2(actual))
    flags = []
    if rem != 0:
        flags.append('inexact')

    # Overflow test: actual >= 2**(emax+1).
    if k >= emax + 1:
        flags = ['overflow', 'inexact']
        to_inf = (mode in ('RNE', 'RNA')) or (mode == 'RUP' and not sign_negative) or (mode == 'RDN' and sign_negative)
        if to_inf:
            bits = encode_inf(1 if sign_negative else 0, ebits, fbits, Eall)
        else:
            bits = encode_max_finite(1 if sign_negative else 0, ebits, fbits, Eall, F)
        return {'bits': format(bits, 'x'), 'flags': flags}

    # Underflow: tininess after rounding.
    if rem != 0 and k < emin:
        flags.append('underflow')

    sign = 1 if sign_negative else 0
    if k < emin:
        # Subnormal.  Here q_exp == emin - fbits and n < F.
        bits = (sign << (ebits + fbits)) | n
        return {'bits': format(bits, 'x'), 'flags': flags}

    # Normal.
    e = k + bias
    target_exp = e - bias - fbits
    sh = q_exp - target_exp
    if sh >= 0:
        sig = n << sh
    else:
        div = 1 << (-sh)
        # exact by construction
        sig = n // div
    frac = sig - F
    bits = (sign << (ebits + fbits)) | (e << fbits) | frac
    return {'bits': format(bits, 'x'), 'flags': flags}


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        request = json.loads(line)
        response = solve(request)
        sys.stdout.write(json.dumps(response) + '\n')


if __name__ == '__main__':
    main()
